import axios from 'axios'
import { default as React, default as useEffect, default as useState } from 'react'

const Members = () => {
    const [members, setMembers] = useState([])

    useEffect(() => {
        const fetchAllMembers = async () => {
            try {
                const res = await axios.get("http://localhost:8800")
                setMembers(res.data)
            } catch(err) {
                console.log(err)
            }
        }
        fetchAllMembers()
    }, [])

    return ( 
        <div>
            <h1>Members List</h1>
            <div className="members">
                {members.map(member => (
                    <div className="member">
                        {member.cover && <img src="" alt="" />}
                        <h2>member.name</h2>
                        <h2>member.membership</h2>
                        <h2>member.age</h2>
                    </div>
                ))}
            </div>
        </div>
    )
}

export default Members
